const agentText = $json.output || '';

const match = agentText.match(/\b[A-Z][A-Z0-9]*-\d+\b/);

if (!match) {
  throw new Error('Could not find Jira Issue Key in AI Agent output.');
}

const issueKey = match[0];

const trigger = $('When chat message received').first();

return [
  {
    json: {
      issueKey: issueKey
    },
    binary: trigger.binary
  }
];
